<h2 style="font-family: 'Arial Black', Arial, sans-serif; font-size: 14pt; text-align: center; margin-top: 30px;">CIERRE REFLEXIVO</h2>
<p>✎ <strong>RESPONDE EN UNA FRASE:</strong> antes de aceptar como correcta la simplificación de una fracción algebraica, ¿qué debes revisar en el denominador original y en los factores comunes?</p>
<hr />
<h3 style="font-family: 'Arial Black', Arial, sans-serif; font-size: 12pt; text-align: left; margin-top: 28px;">REFERENCIAS BIBLIOGRÁFICAS</h3>
<p>Colegio Integrado Simón Bolívar. (2026). <em>Plan de área de Aritmética 8°</em>.</p>
<p>Colegio Integrado Simón Bolívar. (2026). <em>Plan de clase de Aritmética 8°: tercer periodo</em>.</p>
<script>
(function () {

  const root = document.getElementById('fa8_eval_g1');
  if (!root) return;

  const questions = root.querySelectorAll('.fa-q');
  const status = root.querySelector('.fa-status');
  const finalMessage = root.querySelector('.fa-final');
  const resetButton = root.querySelector('.fa-reset');

  let answered = 0;
  let correct = 0;
  const total = questions.length;

  function updateStatus() {

    status.textContent =
      'Seguimiento formativo: Preguntas respondidas: ' +
      answered + ' de ' + total +
      '. Respuestas correctas: ' + correct + '.';

    if (answered === total) {

      finalMessage.textContent =
        'Evaluación completada. Revisa la retroalimentación y corrige en tu cuaderno los procedimientos que necesites ajustar.';

    }

  }

  questions.forEach(function (question) {

    const buttons = question.querySelectorAll('.fa-opt');
    const feedback = question.querySelector('.fa-feedback');

    buttons.forEach(function (button) {

      button.addEventListener('click', function () {

        if (question.getAttribute('data-done') === '1') return;

        question.setAttribute('data-done', '1');
        answered++;

        const isCorrect =
          button.getAttribute('data-correct') === '1';

        if (isCorrect) {

          correct++;
          feedback.setAttribute('data-state', 'correct');

        } else {

          feedback.setAttribute('data-state', 'incorrect');

        }

        feedback.textContent =
          button.getAttribute('data-feedback');

        buttons.forEach(function (item) {
          item.disabled = true;
        });

        updateStatus();

      });

    });

  });


  resetButton.addEventListener('click', function () {

    answered = 0;
    correct = 0;

    questions.forEach(function (question) {

      question.removeAttribute('data-done');

      const feedback =
        question.querySelector('.fa-feedback');

      feedback.textContent = '';
      feedback.removeAttribute('data-state');

      question.querySelectorAll('.fa-opt')
      .forEach(function (button) {
        button.disabled = false;
      });

    });

    finalMessage.textContent = '';

    updateStatus();

  });

  updateStatus();

})();
</script>
</div>
</div>
</div>
